<?php

declare(strict_types=1);

namespace Ameos\AmeosForm\Tests\Unit\Fixtures;

use TYPO3\CMS\Extbase\DomainObject\AbstractEntity;

/**
 * Entity with typed setters, as generated by modern Extbase models
 */
final class TypedMovie extends AbstractEntity
{
    public string $title = '';
    public int $year = 0;
    public bool $favorite = false;
    public float $score = 0.0;
    public ?\DateTime $releaseDate = null;
    public ?\DateTimeImmutable $immutableDate = null;
    public string $tags = '';
    public ?string $comment = 'initial';
    public int $setterCalls = 0;

    public function getTitle(): string
    {
        return $this->title;
    }

    public function setTitle(string $title): void
    {
        $this->title = $title;
    }

    public function getYear(): int
    {
        return $this->year;
    }

    public function setYear(int $year): void
    {
        $this->year = $year;
    }

    public function getFavorite(): bool
    {
        return $this->favorite;
    }

    public function setFavorite(bool $favorite): void
    {
        $this->favorite = $favorite;
    }

    public function getScore(): float
    {
        return $this->score;
    }

    public function setScore(float $score): void
    {
        $this->score = $score;
    }

    public function getReleaseDate(): ?\DateTime
    {
        return $this->releaseDate;
    }

    public function setReleaseDate(?\DateTime $releaseDate): void
    {
        $this->setterCalls++;
        $this->releaseDate = $releaseDate;
    }

    public function getImmutableDate(): ?\DateTimeImmutable
    {
        return $this->immutableDate;
    }

    public function setImmutableDate(?\DateTimeImmutable $immutableDate): void
    {
        $this->immutableDate = $immutableDate;
    }

    public function getTags(): string
    {
        return $this->tags;
    }

    public function setTags(string $tags): void
    {
        $this->tags = $tags;
    }

    public function getComment(): ?string
    {
        return $this->comment;
    }

    public function setComment(?string $comment): void
    {
        $this->comment = $comment;
    }
}
